mapper.select:
SELECT MESSAGE_NUM, SUBSTR(MESSAGE_NUM, 1, 2) AS MESSAGE_GUBUN, MESSAGE_TYPE_CD, MESSAGE_TEXT_KO, MESSAGE_TEXT_EN, MESSAGE_TEXT_ZH, MESSAGE_TEXT_JA, MESSAGE_TEXT_OT, REMARK FROM SYS_MESSAGE WHERE 1 = 1
AND SUBSTR(MESSAGE_NUM, 1, 2) = #{messageGubun}
AND MESSAGE_TYPE_CD = #{messageType}
AND MESSAGE_TEXT_KO LIKE '%' || #{messageText} || '%'
ORDER BY MESSAGE_NUM
